func (s MailDomainServiceServer) Erase(ctx context.Context, req *rstr.MailDomainRef) (*rstr.MailDomainEraseResponse, error) {
	p, err := MailDomainPick(req)
	if err != nil {
		return nil, err
	}
	p, err = s.narrow(ctx, p)
	if err != nil {
		return nil, err
	}

	tx, err := ent1.JoinTx[*ent.Client, *ent.Tx](ctx, s.Db, s.Rec != nil)
	if err != nil {
		return nil, err
	}
	defer tx.Close()

	st := s
	st.Db = tx.Db

	var k any
	if s.Rec != nil {
		v, err := st.Db.MailDomain.Query().Where(p).OnlyId(ctx)
		if err != nil {
			if ent.IsNotFound(err) {
				return &rstr.MailDomainEraseResponse{}, nil
			}
			return nil, err
		}

		k = v
		p = maildomain.And(p, maildomain.IdEQ(v))
	}

	u := st.Db.MailDomain.Update().Where(p)
	u.SetDateErased(st.now())
	u.SetDateUpdated(st.now())
	n, err := u.Save(ctx)
	if err != nil {
		return nil, err
	}
	if n > 0 {
		if err := record(ctx, s.Rec, st.Db, Change{
			By:  rstr.MailDomainService_Erase_FullMethodName,
			Key: k,
		}); err != nil {
			return nil, err
		}
	}
	if err := tx.Commit(); err != nil {
		return nil, err
	}
	res := &rstr.MailDomainEraseResponse{}
	res.SetErased(n > 0)

	return res, nil
}

// MailDomainPick answers with the predicate this reference selects on,
// among the rows that are still here.
//
// Erasure is part of the reference and not only part of a read's scope,
// because a reference to a MailDomain is composed into the reference of
// whatever names one: an index over an edge asks this for a predicate and
// puts it inside `HasMailDomainWith`, where no narrowing of a MailDomain
// is ever applied. A child of an erased row would otherwise be readable by
// naming its parent.
func MailDomainPick(req *rstr.MailDomainRef) (predicate.MailDomain, error) {
	p, err := pickMailDomain(req)
	if err != nil {
		return nil, err
	}

	return maildomain.And(maildomain.DateErasedIsNil(), p), nil
}

func pickMailDomain(req *rstr.MailDomainRef) (predicate.MailDomain, error) {
	switch req.WhichKey() {
	case rstr.MailDomainRef_Id_case:
		if v, err := entuuid.FromBytes(req.GetId()); err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "id: %s", err)
		} else {
			return maildomain.IdEQ(v), nil
		}
	case rstr.MailDomainRef_At_case:
		k := req.GetAt()
		ps := make([]predicate.MailDomain, 0, 2)
		if p, err := TenantPick(k.GetTenant()); err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "at.tenant: %s", err)
		} else {
			ps = append(ps, maildomain.HasTenantWith(p))
		}
		ps = append(ps, maildomain.NameEQ(k.GetName()))
		return maildomain.And(ps...), nil
	case rstr.MailDomainRef_Key_not_set_case:
		return nil, status.Errorf(codes.InvalidArgument, "key not set: MailDomain")
	default:
		return nil, status.Errorf(codes.Unimplemented, "unknown type of key: %s", req.WhichKey())
	}
}
